(()=>{
 const $=id=>document.getElementById(id);let articles=[],filter='all',lastFetch=0,loading=false,generation=0,feedSummary='';
 const goal=document.createElement('dialog');goal.className='goal-intro';goal.setAttribute('aria-label','Un giocatore calcia e segna. Benvenuto nella sezione calcio.');goal.innerHTML=`<div class="goal-top"><span>DV / MATCHDAY</span><button type="button">Salta animazione ↗</button></div><svg class="goal-pitch" viewBox="0 0 1000 600" aria-hidden="true"><defs><linearGradient id="goalSky" x2="0" y2="1"><stop stop-color="#090f20"/><stop offset="1" stop-color="#273e4e"/></linearGradient><pattern id="goalNet" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" fill="none" stroke="#fff" stroke-opacity=".4" stroke-width="1"/></pattern></defs><rect width="1000" height="600" fill="url(#goalSky)"/><path d="M0 320 Q500 190 1000 320V600H0Z" fill="#1c423a"/><path d="M0 390L1000 310M0 550L1000 380" stroke="#254e43" stroke-width="45"/><path d="M0 570L990 375M0 350L990 310" stroke="#bed5c2" stroke-opacity=".5" stroke-width="3"/><path d="M620 560L575 343L990 315" fill="none" stroke="#bed5c2" stroke-opacity=".5" stroke-width="3"/><g class="goal-net"><path d="M733 195L933 160L977 355L747 397Z" fill="url(#goalNet)" stroke="#f7efe0" stroke-width="7"/><path d="M733 195L783 230L968 197L933 160M783 230L798 381M783 230L747 397" fill="none" stroke="#e9e4d6" stroke-opacity=".5" stroke-width="3"/></g><ellipse cx="278" cy="506" rx="78" ry="13" fill="#071e18" opacity=".6" class="goal-shadow"/><g class="goal-player"><g transform="translate(260 305)"><circle cx="0" cy="-86" r="25" fill="#b47d5c"/><path d="M-24-95Q-7-124 21-101L24-88L-23-92Z" fill="#171718"/><path d="M-13-63L14-63L35 23L-37 23Z" fill="#239ecd"/><path d="M-13-63L0-63L0 23L-37 23Z" fill="#b52c3c"/><path d="M-36 16L35 16L34 59L-2 60L-10 44L-15 60L-45 56Z" fill="#102441"/><g class="goal-arm-left"><path d="M-22-49L-65-12L-85-40" fill="none" stroke="#b47d5c" stroke-width="17" stroke-linecap="round"/></g><g class="goal-arm-right"><path d="M23-49L58-15L85-24" fill="none" stroke="#b47d5c" stroke-width="17" stroke-linecap="round"/></g><g class="goal-plant-leg"><path d="M-26 51L-42 110L-31 174" fill="none" stroke="#b47d5c" stroke-width="23" stroke-linecap="round"/><path d="M-41 118L-31 173" stroke="#f2eadb" stroke-width="25"/><path d="M-44 174L-16 174L7 187L-45 190Z" fill="#f3d269"/></g><g class="goal-kick-leg"><path d="M19 52L47 109L26 165" fill="none" stroke="#b47d5c" stroke-width="23" stroke-linecap="round"/><path d="M45 119L26 165" stroke="#f2eadb" stroke-width="25"/><path d="M12 165L39 163L63 177L13 184Z" fill="#f3d269"/></g><text x="-8" y="-5" fill="#fff" font-family="Arial" font-size="29" font-weight="bold">9</text></g></g><g class="goal-ball"><circle r="17" fill="#fff5df"/><path d="M0-8L8-2L5 7H-5L-8-2Z" fill="#182232"/><path d="M0-17V-12M16 4L11 3M-14 9L-10 6" stroke="#182232" stroke-width="3"/></g></svg><div class="goal-caption"><span>IL TUO POSTO È QUI.</span><strong>GOOOL.</strong><p>Bologna & Napoli / La tua passione entra in campo.</p></div>`;document.body.append(goal);
 let goalTimer,openTimer;const reduced=()=>matchMedia('(prefers-reduced-motion:reduce)').matches||document.body.classList.contains('motion-paused');
 function closeGoal(){clearTimeout(goalTimer);clearTimeout(openTimer);goal.close();goal.classList.remove('is-playing')}
 function playGoal(){closeGoal();if(reduced()||!$('mod-calcio').classList.contains('active')||!$('authOverlay').classList.contains('hidden'))return;goal.showModal();void goal.offsetWidth;goal.classList.add('is-playing');goalTimer=setTimeout(closeGoal,2900)}
 goal.querySelector('button').onclick=closeGoal;goal.addEventListener('cancel',e=>{e.preventDefault();closeGoal()});$('replayGoal').onclick=playGoal;addEventListener('space:motion',()=>{if(reduced())closeGoal()});matchMedia('(prefers-reduced-motion:reduce)').addEventListener('change',()=>{if(reduced())closeGoal()});document.addEventListener('visibilitychange',()=>{if(document.hidden)closeGoal()});
 function draw(){const list=articles.filter(x=>filter==='all'||x.team===filter);$('footballNews').replaceChildren();for(const item of list){const card=document.createElement('article');card.className='news-card '+item.team;const top=document.createElement('div');top.className='news-topline';top.textContent=item.team==='bologna'?'BOLOGNA / ROSSOBLÙ':'NAPOLI / AZZURRI';const h=document.createElement('h2'),a=document.createElement('a');a.textContent=item.title;a.href=item.url;a.target='_blank';a.rel='noopener noreferrer';h.append(a);const footer=document.createElement('p');footer.textContent=item.source+(item.publishedAt?' · '+new Date(item.publishedAt).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'');card.append(top,h,footer);$('footballNews').append(card)}if(!loading&&!list.length)$('footballNews').textContent='Nessuna notizia disponibile per questa selezione. Puoi consultare le fonti ufficiali qui sotto.';}
 async function fetchNews(force=false){if(loading||(!force&&lastFetch&&Date.now()-lastFetch<300000)){draw();return}loading=true;const id=++generation;$('refreshFootball').disabled=true;$('footballStatus').textContent='Caricamento delle notizie di Bologna e Napoli…';try{const results=await Promise.allSettled(['bologna','napoli'].map(async team=>{const r=await fetch('/api/football-news?team='+team,{signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok||!Array.isArray(data.articles))throw Error();return data.articles.filter(x=>x.team===team&&typeof x.title==='string'&&/^https:\/\//.test(x.url))}));if(id!==generation)return;const fresh=results.flatMap(r=>r.status==='fulfilled'?r.value:[]);const failures=results.filter(r=>r.status==='rejected').length;if(fresh.length){articles=fresh.sort((a,b)=>(Date.parse(b.publishedAt)||0)-(Date.parse(a.publishedAt)||0));lastFetch=Date.now();feedSummary=failures?'Una delle due rassegne non risponde. Mostro le notizie disponibili.':'Rassegna aggiornata alle '+new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})+' · Fonti via Google News.'}else feedSummary=articles.length?'Aggiornamento non riuscito. Restano le notizie caricate in precedenza.':'Rassegna momentaneamente non disponibile. Riprova o apri i siti ufficiali qui sotto.';$('footballStatus').textContent=feedSummary;}catch{$('footballStatus').textContent='Connessione non disponibile. Riprova.'}finally{if(id===generation){loading=false;$('refreshFootball').disabled=false;draw()}}}
 document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{filter=b.dataset.team;document.querySelectorAll('[data-team]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw()});$('refreshFootball').onclick=()=>fetchNews(true);
 addEventListener('workspace:module',e=>{closeGoal();if(e.detail==='calcio'){fetchNews();openTimer=setTimeout(playGoal,450)}});new MutationObserver(()=>{if(!$('authOverlay').classList.contains('hidden'))closeGoal()}).observe($('authOverlay'),{attributes:true,attributeFilter:['class']});addEventListener('pagehide',closeGoal);
})();
